def main():
    simulate = "--simular" in sys.argv
    root = os.getcwd()
    if not os.path.exists(os.path.join(root, "xadrez.py")):
        print("ERRO: rode este arquivo dentro da pasta do projeto (a que tem o xadrez.py).")
        return 1
    archive = zipfile.ZipFile(io.BytesIO(base64.b64decode("".join(PAYLOAD.split()))))
    stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_root = os.path.join(root, "backup_atualizar_" + stamp)
    changed = created = same = 0
    for info in archive.infolist():
        rel = info.filename
        target = os.path.normpath(os.path.join(root, rel))
        if not target.startswith(root + os.sep):
            print("IGNORADO (caminho suspeito):", rel)
            continue
        data = archive.read(rel)
        if os.path.exists(target):
            with open(target, "rb") as handle:
                current = handle.read()
            if hashlib.sha256(current).digest() == hashlib.sha256(data).digest():
                same += 1
                continue
            changed += 1
            print(("[SIMULADO] ATUALIZA " if simulate else "ATUALIZA ") + rel)
            if not simulate:
                backup = os.path.join(backup_root, rel)
                os.makedirs(os.path.dirname(backup), exist_ok=True)
                with open(backup, "wb") as handle:
                    handle.write(current)
        else:
            created += 1
            print(("[SIMULADO] NOVO     " if simulate else "NOVO     ") + rel)
        if not simulate:
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with open(target, "wb") as handle:
                handle.write(data)
    print()
    print(f"{VERSAO}: {changed} atualizados, {created} novos, {same} já iguais.")
    if simulate:
        print("Nada foi gravado (modo simulação).")
    elif changed:
        print("Cópias dos arquivos antigos em:", os.path.relpath(backup_root, root))
    print("Próximo passo: pip install -r requirements.txt e reinicie o servidor.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
